-- The Juicer weapons from Rifts World Book Ten: Juicer Uprising, printed 71-76.
-- Sixteen rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-juicer-uprising-gear-b.sql
--
-- The book has a TEXT LAYER, so this was read with scripts/read-columns.py and
-- transcribed rather than OCR'd. The printed-to-PDF offset is ZERO.
--
-- SECOND OF THREE GEAR BATCHES. See add-juicer-uprising-gear-a.sql for the
-- conventions: a price RANGE stores its low end in `cost` with the printed range
-- in `cost_note`, and conditional or dice-valued damage stays as printed text.
--
-- AMMUNITION AND ACCESSORY PRICES ARE cost_note, NOT ROWS. The NG-11S prices its
-- explosive shells at 150 and its APRJ rounds at 200; the Pepperbox prices its
-- batteries at 100 and a speedloader at 75; both flamethrowers price a
-- disposable tank. None of those is a separate item in the book - they are the
-- running cost of the gun, printed on the gun's own Black Market Cost line - so
-- they stay on the row that owns them rather than becoming rows nobody would
-- ever find by name.
--
-- THREE TEXT-LAYER REPAIRS, all the same failure: l for 1 and O for 0.
--   "NG-11S "Sawed-OfT"   is  NG-11S "Sawed-Off"   (a final T for a double f)
--   "the NG-1 IS"          is  the NG-11S           (a space and an I for a 1)
--   "!D6xlO", "!D4xlO+10"  are 1D6x10 and 1D4x10+10
-- Every one is fixed by knowing what the value has to look like. A better
-- reader does not fix any of them - this is typesetting damage in the PDF's own
-- text layer, not a misread.
--
-- Pure ASCII with LF line endings, comments included, per PR #93 and #101.
-- ON CONFLICT (slug) DO NOTHING, not DO UPDATE: every row here is new, and
-- nothing in this file should ever overwrite a curated value.

INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage,
                  range, payload, rate_of_fire, description, source_book) VALUES
('fiws-forearm-integral-weapon-system', 'FIWS (Forearm Integral Weapon System)', 'rifts', 'weapon', 5.0, 24000, 'Black market 24,000 credits', 'Particle beam: 5D6 M.D. per single blast, or 1D6x10 M.D. per double blast, which counts as one attack but uses two shots. Vibro-blades, three per arm: 3D6 M.D.', 1, 'Particle beam 500 feet (152 m); blades hand to hand', 'Long E-Clip: 30 single shots or 15 double shots', 'Single shots only', 'Developed for the Chi-Town Special Forces Battalion. Colonel Lyboc, who ran the project, is always trying to make a buck, so the blueprints were "stolen" by the Black Market and pirated FIWS are now on sale across North America. It looks like a thick, heavy forearm plate: two thick-barrelled particle beam projectors over and under the wrist, a thinner targeting laser at +1 to strike, and three vibro-blades that spring out at a flick of the wrist. Meant for close assault - the particle beams are powerful and short-ranged. Combat trials showed a team of FIWS-equipped Juicers who get within 500 feet (152 m) of a tank will destroy it before it destroys them. The weight adds to the armor. Juicer Uprising p.71-72.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('wi-lp3-pepperbox-laser', 'WI-LP3 Pepperbox Laser', 'rifts', 'weapon', 1.0, 12000, 'Black market 12,000 credits for the gun; each battery costs 100 credits, and a speedloader that loads all four at once costs 75', 'Single shot 1D4 M.D.; double 2D4 M.D.; triple 3D4 M.D.; quadruple 4D4 M.D., which empties the payload.', 1, '100 feet (30.5 m)', 'Four shots, one per battery, each roughly the size of a shotgun cell. Reloading takes four melee actions, or one with a speedloader.', 'Single, double, triple or quadruple shots - all count as one melee attack', 'A common holdout pistol whose four barrels are built into a solid block, small enough to hide in a pocket or a boot (+4% on concealment rolls). It carries four mini-batteries rather than an E-Clip, one priming and firing per barrel, and has a breakaway action that ejects the spent ones. Weak and short-ranged, and quite capable of killing at 100 feet. Popular with City Rats, gang-bangers, gamblers, assassins and other undesirables; weapon detectors will find it, but a cursory search will not. Juicers keep one as a backup or a nasty surprise, and assassins carry them where visible weaponry would get them stopped. Weight under one pound. Juicer Uprising p.72.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('wi-ft1-plasma-flamethrower', 'WI-FT1 Plasma Flamethrower (W.I.)', 'rifts', 'weapon', 30.0, 30000, 'Black market 30,000 credits; a plasma tank costs 1,200 credits and is disposable', 'Short plasma burst 3D6 M.D. Concentrated burst, counting as two attacks over seven seconds, 1D4x10+10 M.D. Or cover an area: 10 feet (3 m) per melee attack, so four attacks blanket 40 feet (12.2 m), and everybody in it takes 2D6 M.D.', 1, '500 feet (152 m)', 'Standard E-Clip 8 bursts, long E-Clip 16; a plasma tank holds 100 shots', 'Single shot or concentrated burst', 'A collaboration between Golden Age Weaponsmiths and Wellington Industries. Golden Age recognised the flamethrower as an ideal shock weapon and Wellington adapted plasma systems into a short-ranged but continuous stream of mega-damage flame. Primarily a terrorist weapon, and also ideal against certain monsters, lightly armoured ground troops, vehicles, bunkers and hardened positions. 30 lbs (13.5 kg), or 45 lbs (20.5 kg) with the plasma tank. Juicer Uprising p.72.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('wi-nft-1-napalm-p-flame-thrower', 'WI-NFT-1 Napalm-P Flame Thrower', 'rifts', 'weapon', 45.0, 40000, 'Black market 40,000 credits; a plasma tank costs 2,000 credits and is disposable', 'Plasma burst 3D6 M.D. Concentrated burst, counting as two attacks, 1D4x10+10 M.D. Or cover 10 feet (3 m) per melee attack for 2D6 M.D. to everybody in the area. AND ANYTHING HIT KEEPS BURNING: 2D6 M.D. every melee round for 1D4 minutes.', 1, '500 feet (152 m)', 'A Napalm-P tank holds 100 shots', 'Single shot or concentrated burst only', 'Wellington Industries built this on pre-Rifts technology to project LONG-LIVED plasma: it does not dissipate in ten or twenty seconds but burns for 1D4 minutes, and a well-placed shot will consume a man in light body armor in a matter of minutes. The only escape is to roll in dirt or sand - water will NOT put it out - for one entire melee round of fifteen seconds, until the substance is rubbed off. The fuel tank is a liability: a called shot against its 15 M.D.C. destroys it, and it explodes for 2D6x10 M.D. to a 30 foot (9.1 m) radius. Juicer Uprising p.73.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('ng-ip7-ion-pulse-rifle', 'NG-IP7 Ion Pulse Rifle', 'rifts', 'weapon', 7.0, 20000, 'Black market 20,000 credits', 'Single shot 3D6 M.D., or a multiple pulse burst at 1D4x10 M.D., which counts as one attack but consumes three shots.', 1, '1,600 feet (488 m)', '30 shots', 'Standard', 'A combat rifle in a shortened bull-pup layout, compact and easy to carry and conceal. Liked by Juicers, security forces and urban combat units. Juicer Uprising p.73.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('ng-45lp-long-pistol', 'NG-45LP "Long Pistol"', 'rifts', 'weapon', 5.0, 15000, 'Black market 15,000 credits', '5D6 M.D. per shot.', 1, '1,200 feet (365 m)', '8 shots', 'Single shots only', 'A long-barrelled pistol with nearly the range of a rifle, firing a powerful particle beam. Juicers like it for the intimidation, and it is popular with pilots - small enough for a weapons compartment and almost as good as a rifle - as well as outlaws and travellers. Of late it has become a symbol of manhood and toughness. Juicer Uprising p.73.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('ng-11s-sawed-off', 'NG-11S "Sawed-Off"', 'rifts', 'weapon', 3.0, 4000, 'Black market 4,000 credits; explosive shells 150 credits each, APRJ rounds 200 credits each', 'Varies with ammunition. Shotgun shell 4D6 S.D.C., or 8D6 for a double blast at one target. Solid slugs 5D6 S.D.C., or 1D6x10 doubled. Fragmentary explosive shell 2D6 M.D. to a 10 foot (3 m) diameter, or 3D6 M.D. to 20 feet (6.1 m) doubled. Plasma explosive shell 3D6 M.D. to a 6 foot (1.8 m) area, or 5D6 M.D. to 12 feet (3.6 m) doubled. APRJ armor-piercing ramjet rounds 3D6 M.D., or 6D6 M.D. doubled. A double blast counts as one melee attack.', 1, 'Shotgun shells and slugs 300 feet (91.4 m); explosive shells and APRJ 500 feet (152 m)', 'Two shots; reloading takes one melee round', 'Single or double shot only', 'A double-barrelled sawed-off shotgun with a pistol grip. This .60 calibre smoothbore fires ordinary 12-gauge shells, special explosive rounds equivalent to small grenades, and ramjet rounds built to crack M.D.C. body armor - fired like a bullet, then a secondary rocket booster drives the heavy M.D.C. slug to rail gun speeds. The drawback is two rounds at a time. Juicers, bandits and adventurers carry 20 to 50 rounds in ammo belts anyway, and some Juicers have adopted a "bandido" look with crisscrossed belts across the chest. Juicer Uprising p.73-74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('zapper-gun-uti', 'Zapper Gun (UTI)', 'rifts', 'weapon', 8.0, 30000, 'Black market 30,000 credits', '2D4 M.D. In addition, humans and most humanoids must save at 14 or higher or take 1D6 S.D.C. - M.D.C. for a supernatural creature - lose initiative, and be at -1 to all combat actions for 1D4 melee rounds.', 1, '1,000 feet (305 m)', '15 shots with a standard E-Clip', 'Single shots only', 'The latest from Ultra-Tech Incorporated: bulky, with a stubby barrel and a retractable stock, fired one-handed like a machine pistol or two-handed like a sub-machinegun. It projects an ionising beam that discharges a powerful electrical charge on touching M.D.C. alloy, arcing hard enough to melt the material and deliver a stunning or lethal shock to most living things. THE BEAMS ARE -2 TO DODGE, because the ionising beam is invisible until it touches and the charge arrives instantly. It reaches people in body armor and most light power armor; vehicles, robots with a reinforced pilot compartment, and heavy power armor protect their crews completely. Supernatural beings immune to electricity take nothing, and powerful entities may have +2 to +6 to save on top of P.E. bonuses at the G.M.''s discretion. Juicer Uprising p.74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('deadball-grenade', 'Deadball Grenade', 'rifts', 'weapon', 1.0, 1000, 'Black market 1,000 credits per grenade', '3D6 M.D. to a 20 foot (6.1 m) area.', 1, 'With W.P. Deadball up to 200 feet (61 m); otherwise 120 feet (36.5 m)', NULL, 'One', 'Built for players and fans of the Juicer sport: an explosive charge inside a highly elastic plastic sheath, shaped like a ball roughly the size of a baseball. Unlike a true Deadball it has no spikes, so it ricochets off almost anything, and its detonator can be set to go off after one, two or up to FIVE impacts. A trained Deadball player can bounce it around corners, into small holes, or into a tank''s crew compartment. Without W.P. Deadball the same trick is a called shot at -4 to strike per ricochet. Juicer Uprising p.74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('vibro-deadball', 'Vibro-Deadball', 'rifts', 'weapon', 1.0, 4000, 'Black market 4,000 credits', '2D4 M.D.', 1, '200 feet (61.0 m)', NULL, 'A throw counts as one hand to hand attack', 'Looks like the play ball of the popular Juicer game, but its spikes always come out after a throw and each carries a vibro-field. A trained Deadball player can line up a strike that hits a target, slashes it, and ricochets back to him from as far as 200 feet (61 m). The spikes retract automatically after the first impact. Juicer Uprising p.74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('holdout-speed-holsters', 'Holdout Speed Holsters', 'rifts', 'gear', NULL, 1500, 'Black market 1,500 credits', NULL, 0, NULL, NULL, NULL, 'Weapon accessory: a holster with a spring that flings the gun into the wearer''s hand at a flick of the wrist, usually worn on the forearm. At the start of a fight where no guns are drawn yet, the character is +3 on initiative to be first to draw and fire - and if he is the one who starts it, the shot counts as an ambush or sneak attack and wins initiative automatically. Juicer Uprising p.74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('advanced-thermal-sights', 'Advanced Thermal Sights', 'rifts', 'gear', NULL, 15000, 'Black market 15,000 credits for goggles, 30,000 to build them into armor', NULL, 0, NULL, NULL, NULL, 'Weapon accessory. Thermal sights existed before the Rifts and had every military application from night fighting to seeing inside buildings. These sense heat signatures THROUGH walls and other obstructions - assassins use them to find a target and then shoot him through a flimsy S.D.C. wall. Only thick reinforced M.D.C. walls, four inches or more, block the reading enough to foil them. Juicer Uprising p.74.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('wi-c8-close-combat-weapon-system', 'WI-C8 Close Combat Weapon System (Juicer Chainsaw)', 'rifts', 'weapon', 20.0, 30000, 'Black market 30,000 credits', 'Activated, the chainsaw inflicts 5D6 M.D.', 1, 'Hand to hand combat only', 'E-Clip; one hour of continuous use, and each activation drains at least a minute of charge even if used for less', 'Equal to hand to hand attacks', 'A Wellington Industries product that is nothing more than a chainsaw with M.D.C. teeth sharpened to a near mono-molecular edge. The bits use cheap recycled M.D.C. alloy, often from wrecked power armor; the sharpening is what costs. Heavy and cumbersome - PENALTIES: usable without penalty only at P.S. 22 or higher, or any supernatural P.S.; weaker characters are -4 to strike and -6 to parry. Archaic in an age of ranged weapons and enormously intimidating: a favourite in gladiatorial combat, and the Juicer Army of Liberation has raised shock troops armed with nothing else. CS detachments have run from a charging mass of chainsaw-wielding maniacs. Juicer Uprising p.75.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('wi-cl8-multi-purpose-weapon-system', 'WI-CL8 Multi-Purpose Weapon System (W.I.)', 'rifts', 'weapon', 28.0, 45000, 'Black market 45,000 credits', 'Chainsaw 5D6 M.D.; laser 3D6 M.D.', 1, 'Laser 2,000 feet (610 m); chainsaw hand to hand only', 'Two E-Clips: the laser has 20 shots, and the second powers the chainsaw for one hour of continuous use, draining at least a minute per activation', 'Laser standard; chainsaw hand to hand', 'The Juicer Chainsaw with a laser rifle mounted over the saw motor - heavier, but with a long-range attack. PENALTIES: -1 to strike with either the laser or the saw even at P.S. 24 or higher or any supernatural P.S.; weaker characters are -5 to strike and -7 to parry with the saw and -3 to strike with the laser, because the weapon is heavy and unbalanced. Juicer Uprising p.75.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('ja-12-laser-rifle', 'JA-12 Laser Rifle', 'rifts', 'weapon', 13.0, 50000, 'Black market 50,000 credits', 'Single shot 4D6 M.D. Triple-pulse shot 1D6x10+10 M.D., counting as one melee attack but forfeiting the targeting bonus. Each grenade 3D6 M.D. to a 10 foot (3 m) radius.', 1, 'Laser 4,000 feet (1,220 m); grenade 2,000 feet (610 m)', 'Standard E-Clip 10 shots, long E-Clip 30; a built-in rechargeable energy canister holds another 30; the grenade launcher has a four-shot pump magazine reloaded by hand', 'Standard', 'A recreation of a pre-Rifts German design meant primarily for Juicers. Like the JA-11 it carries an energy canister as well as an E-Clip, and it was optimised for BOTH sniping and assault: accurate single shots, multiple-pulse bursts that give up the targeting, and a grenade launcher. Since production began it has been known as "the one-man-army rifle." BONUS: +1 to strike on aimed or called shots, cumulative with other bonuses, and no bonus for auto-pulse or grenades. Its shortcoming is a fixed frequency - the multiple pulse system cannot be reset - which makes it much less effective against Glitter Boys and other laser-resistant targets. Juicer Uprising p.76.', 'Rifts World Book 10: Juicer Uprising p.71-76'),
('ng-h5-holdout-ion-pistol', 'NG-H5 Holdout Ion Pistol', 'rifts', 'weapon', 1.0, 50000, 'Black market 50,000 credits', '1D4+1 M.D. per shot.', 1, '200 feet (61.0 m)', '6 shots', 'Single shots only', 'Made by Northern Gun exclusively for its own spy and security organisations, and secret until the Black Market got hold of a shipment of several thousand. Knockoffs are now sold across North America, and use or possession is ILLEGAL in most civilised parts of the continent including the Coalition States - finding one on anybody is usually grounds for imprisonment on suspicion of being an assassin. Derringer-sized, using a special mini-energy clip, it fits in the palm and hides in a boot, a sleeve holster or under light clothing (+6% to concealment). More importantly the originals were built to foil weapon detectors: common systems at medium and low security have NO chance of finding one, and advanced systems at high security have 01-40% at the G.M.''s discretion. Juicer assassins love it, and some carry three or four. Weight under one pound. Juicer Uprising p.76.', 'Rifts World Book 10: Juicer Uprising p.71-76')
ON CONFLICT (slug) DO NOTHING;

-- Read the result back rather than trusting the exit code.
SELECT COUNT(*) AS juicer_uprising_gear_b FROM gear WHERE source_book = 'Rifts World Book 10: Juicer Uprising p.71-76';
SELECT slug, name, cost, is_mega_damage FROM gear
 WHERE slug IN ('ja-12-laser-rifle', 'ng-11s-sawed-off', 'deadball-grenade', 'wi-c8-close-combat-weapon-system')
 ORDER BY slug;

-- Records this run. One row per run rather than per file: every statement above
-- guards itself, so this script is safe to re-run and safe to run early.
-- See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-juicer-uprising-gear-b.sql');
